     6	type ModalCardStyleInterpolator = (
     7	    isSmallScreenWidth: boolean,
     8	    isFullScreenModal: boolean,
     9	    shouldUseNarrowLayout: boolean,
    10	    stackCardInterpolationProps: StackCardInterpolationProps,
    11	    outputRangeMultiplier?: number,
    12	) => StackCardInterpolatedStyle;
    13	type CreateModalCardStyleInterpolator = (StyleUtils: StyleUtilsType) => ModalCardStyleInterpolator;
    14	
    15	const createModalCardStyleInterpolator: CreateModalCardStyleInterpolator =
    16	    (StyleUtils) =>
    17	    (isSmallScreenWidth, isFullScreenModal, shouldUseNarrowLayout, {current: {progress}, inverted, layouts: {screen}}, outputRangeMultiplier = 1) => {
    18	        if (shouldUseNarrowLayout) {
    19	            return {
    20	                cardStyle: {
    21	                    opacity: progress,
    22	                },
    23	            };
    24	        }
    25	
    26	        const translateX = Animated.multiply(
    27	            progress.interpolate({
    28	                inputRange: [0, 1],
    29	                outputRange: [outputRangeMultiplier * (isSmallScreenWidth ? screen.width : variables.sideBarWidth), 0],
    30	                extrapolate: 'clamp',
    31	            }),
    32	            inverted,
    33	        );
    34	
    35	        const cardStyle = StyleUtils.getCardStyles(screen.width);
    36	
    37	        if (!isFullScreenModal || isSmallScreenWidth) {
    38	            cardStyle.transform = [{translateX}];
    39	        }
    40	
    41	        return {
    42	            containerStyle: {
    43	                overflow: 'hidden',
    44	            },
